import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import { Link, Navigate, NavLink, Outlet, Route, Routes, useLocation, useNavigate } from 'react-router-dom';
import { Activity, ArrowDownRight, ArrowUpRight, Boxes, Check, ChevronLeft, ChevronRight, CircleAlert, ClipboardList, ExternalLink, Eye, EyeOff, LayoutDashboard, LoaderCircle, LogOut, Menu, Package, Plus, RefreshCw, Search, Settings, Shapes, ShieldCheck, ShoppingBag, SlidersHorizontal, Sparkles, Tags, X } from 'lucide-react';
import { AdminApiError, adminApi } from './api';
import type { AdminUser, Category, Collection, Product, ProductInput, ResourceInput } from './types';

interface AuthValue { admin: AdminUser | null; loading: boolean; refresh: () => Promise<void>; logout: () => Promise<void> }
const AuthContext = createContext<AuthValue | null>(null);
const useAuth = () => { const value = useContext(AuthContext); if (!value) throw new Error('Admin auth provider missing'); return value; };
type Notice = { message: string; type?: 'success'|'error' };
const NoticeContext = createContext<(message: string, type?: 'success'|'error') => void>(() => {});
const useNotice = () => useContext(NoticeContext);
const money = (value?: string | null) => value == null ? '—' : new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(value));
const date = (value?: string) => value ? new Intl.DateTimeFormat('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)) : '—';
const text = (v: FormDataEntryValue | null) => String(v ?? '').trim();
const slugify = (s: string) => s.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

export const AdminApp: React.FC = () => {
  const [admin, setAdmin] = useState<AdminUser|null>(null);
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState<Notice|null>(null);
  const location = useLocation(); const navigate = useNavigate();
  const refresh = useCallback(async () => { try { setAdmin(await adminApi.me()); } catch { setAdmin(null); } finally { setLoading(false); } }, []);
  const logout = useCallback(async () => { try { await adminApi.logout(); } catch { adminApi.resetCsrf(); } setAdmin(null); navigate('/admin/login', { replace: true }); }, [navigate]);
  useEffect(() => { if (location.pathname !== '/admin/login') void refresh(); else setLoading(false); }, [location.pathname, refresh]);
  useEffect(() => { const expired = () => { setAdmin(null); navigate('/admin/login', { replace: true, state: { expired: true } }); }; window.addEventListener('narmira:session-expired', expired); return () => window.removeEventListener('narmira:session-expired', expired); }, [navigate]);
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(null), 4000); return () => window.clearTimeout(timer); }, [notice]);
  const auth = useMemo(() => ({ admin, loading, refresh, logout }), [admin, loading, refresh, logout]);
  const showNotice = useCallback((message: string, type: 'success'|'error' = 'success') => setNotice({ message, type }), []);
  return <AuthContext.Provider value={auth}><NoticeContext.Provider value={showNotice}>
    <div className="admin-app min-h-screen bg-[#F8F5EF] text-[#302820] font-sans">
      <Routes>
        <Route path="/admin/login" element={admin ? <Navigate to="/admin" replace /> : <LoginPage />} />
        <Route path="/admin" element={loading ? <AdminLoading /> : !admin ? <Navigate to="/admin/login" replace state={{ from: location.pathname }} /> : <AdminShell />}>
          <Route index element={<OverviewPage />} />
          <Route path="products" element={<ProductsPage />} />
          <Route path="products/new" element={<ProductEditor />} />
          <Route path="products/:id" element={<ProductEditor />} />
          <Route path="categories" element={<ResourcesPage kind="categories" />} />
          <Route path="collections" element={<ResourcesPage kind="collections" />} />
          <Route path="inventory" element={<InventoryPage />} />
          <Route path="audit" element={<AuditPage />} />
          <Route path="settings" element={<SettingsPage />} />
        </Route>
        <Route path="*" element={<Navigate to="/admin" replace />} />
      </Routes>
      {notice && <div role="status" className={`fixed bottom-5 right-5 z-[80] flex items-center gap-3 border px-5 py-3 shadow-lg ${notice.type === 'error' ? 'bg-[#FFF5F3] border-[#B86B61] text-[#79352F]' : 'bg-[#302820] border-[#B59A68] text-[#F8F5EF]'}`}><span className="h-2 w-2 rounded-full bg-[#B59A68]" />{notice.message}<button aria-label="Dismiss" onClick={() => setNotice(null)}><X size={16}/></button></div>}
    </div>
  </NoticeContext.Provider></AuthContext.Provider>;
};

const AdminLoading = () => <div className="min-h-screen grid place-items-center"><div className="flex items-center gap-3 text-sm text-[#776E62]"><LoaderCircle className="animate-spin" size={18}/>Checking administrator session</div></div>;

const LoginPage: React.FC = () => {
  const { refresh } = useAuth(); const notice = useNotice(); const navigate = useNavigate(); const location = useLocation();
  const [busy, setBusy] = useState(false); const [show, setShow] = useState(false); const [error, setError] = useState('');
  useEffect(() => { if ((location.state as { expired?: boolean } | null)?.expired) setError('Your session expired. Please sign in again.'); }, [location.state]);
  async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); setError(''); setBusy(true); const data = new FormData(event.currentTarget); try { await adminApi.login(text(data.get('email')), text(data.get('password'))); await refresh(); notice('Welcome back to your workspace.'); navigate('/admin', { replace: true }); } catch (e) { const err = e as AdminApiError; const message = err.status === 429 ? 'Too many attempts. Please wait a minute before trying again.' : err.message; setError(message); } finally { setBusy(false); } }
  return <div className="min-h-screen grid lg:grid-cols-[1fr_0.85fr] bg-[#F8F5EF]">
    <div className="relative hidden lg:flex flex-col justify-between overflow-hidden bg-[#632D35] px-16 py-14 text-[#F8F5EF]">
      <div className="absolute inset-0 opacity-[0.08]" style={{ backgroundImage: 'radial-gradient(#eee6d8 1px, transparent 1px)', backgroundSize: '22px 22px' }}/>
      <Link to="/" className="relative font-serif text-3xl tracking-[.22em]">NARMIRA</Link>
      <div className="relative max-w-xl"><div className="mb-7 h-px w-14 bg-[#B59A68]"/><p className="font-serif text-5xl leading-[1.1]">The Soul of Maheshwar,<br/>The Style of Today.</p><p className="mt-6 max-w-sm text-sm leading-7 text-[#F8F5EF]/65">A considered space to care for every detail of your collection.</p></div>
      <p className="relative text-[10px] uppercase tracking-[.25em] text-[#F8F5EF]/45">Private administrator access</p>
    </div>
    <div className="flex items-center justify-center px-6 py-12">
      <form onSubmit={submit} className="w-full max-w-[420px]">
        <Link to="/" className="font-serif text-2xl tracking-[.2em] text-[#632D35] lg:hidden">NARMIRA</Link>
        <div className="mt-14 lg:mt-0"><p className="text-[10px] uppercase tracking-[.24em] text-[#9A8665]">Admin workspace</p><h1 className="mt-3 font-serif text-4xl">Welcome back</h1><p className="mt-3 text-sm text-[#81776B]">Sign in with your administrator account.</p></div>
        {error && <div role="alert" className="mt-7 flex gap-2 border border-[#DAB9B2] bg-[#FFF6F3] p-3 text-sm text-[#79352F]"><CircleAlert size={17} className="mt-0.5 shrink-0"/>{error}</div>}
        <label className="mt-9 block text-xs font-medium text-[#554D44]">Email address<input name="email" type="email" autoComplete="username" required maxLength={254} className="admin-input mt-2" placeholder="you@yourbrand.com"/></label>
        <label className="mt-5 block text-xs font-medium text-[#554D44]">Password<div className="relative mt-2"><input name="password" type={show?'text':'password'} autoComplete="current-password" required maxLength={128} className="admin-input pr-12" placeholder="Enter your password"/><button type="button" aria-label={show?'Hide password':'Show password'} onClick={() => setShow(!show)} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#827769]">{show?<EyeOff size={17}/>:<Eye size={17}/>}</button></div></label>
        <button disabled={busy} className="admin-button-primary mt-8 w-full">{busy?<LoaderCircle size={17} className="animate-spin"/>:<ShieldCheck size={17}/>}Sign in securely</button>
        <Link to="/" className="mt-7 block text-center text-xs text-[#81776B] hover:text-[#632D35]">Return to storefront</Link>
        <p className="mt-12 text-center text-[10px] uppercase tracking-[.17em] text-[#A69B8B]">Protected by NARMIRA secure access</p>
      </form>
    </div>
  </div>;
};

const nav: { label:string; items:{to:string;label:string;icon:typeof LayoutDashboard;end?:boolean;superOnly?:boolean}[] }[] = [
  { label: 'Workspace', items: [{ to:'/admin', label:'Overview', icon:LayoutDashboard, end:true }] },
  { label: 'Catalog', items: [{ to:'/admin/products',label:'Products',icon:ShoppingBag},{to:'/admin/categories',label:'Categories',icon:Shapes},{to:'/admin/collections',label:'Collections',icon:Tags},{to:'/admin/inventory',label:'Inventory',icon:Boxes}] },
  { label: 'Administration', items: [{to:'/admin/audit',label:'Activity log',icon:Activity,superOnly:true},{to:'/admin/settings',label:'Settings',icon:Settings}] },
];
const AdminShell: React.FC = () => {
  const { admin, logout } = useAuth(); const [drawer, setDrawer] = useState(false); const location = useLocation();
  const title = location.pathname.includes('/products/new')?'New product':location.pathname.includes('/products/')?'Edit product':location.pathname.split('/').filter(Boolean).at(-1) ?? 'Overview';
  const sidebar = <aside className="flex h-full flex-col bg-[#302820] text-[#F8F5EF]">
    <Link to="/admin" className="border-b border-white/10 px-7 py-6"><span className="font-serif text-[22px] tracking-[.19em]">NARMIRA</span><span className="mt-1 block text-[9px] uppercase tracking-[.25em] text-[#B59A68]">Atelier · Admin</span></Link>
    <nav className="flex-1 space-y-7 overflow-y-auto px-4 py-7">{nav.map(group=><div key={group.label}><p className="mb-2 px-3 text-[9px] uppercase tracking-[.2em] text-white/35">{group.label}</p><div className="space-y-1">{group.items.filter(item=>!item.superOnly||admin?.role==='SUPER_ADMIN').map(item=><NavLink key={item.to} to={item.to} end={item.end} onClick={()=>setDrawer(false)} className={({isActive})=>`flex items-center gap-3 px-3 py-2.5 text-[12px] transition-colors ${isActive?'bg-[#632D35] text-white':'text-white/60 hover:bg-white/5 hover:text-white'}`}><item.icon size={16} strokeWidth={1.6}/>{item.label}</NavLink>)}</div></div>)}</nav>
    <div className="border-t border-white/10 p-4"><div className="flex items-center gap-3 px-2 py-2"><div className="grid h-9 w-9 place-items-center bg-[#B59A68]/20 font-serif text-lg text-[#D6C39F]">{admin?.name?.slice(0,1).toUpperCase()}</div><div className="min-w-0 flex-1"><p className="truncate text-xs">{admin?.name}</p><p className="mt-1 truncate text-[9px] uppercase tracking-[.12em] text-white/40">{admin?.role.replace('_',' ')}</p></div><button onClick={() => void logout()} aria-label="Sign out" title="Sign out" className="p-2 text-white/45 hover:text-white"><LogOut size={16}/></button></div><Link to="/" className="mt-2 flex items-center gap-2 px-2 py-2 text-[10px] text-white/35 hover:text-white/70">View storefront <ExternalLink size={12}/></Link></div>
  </aside>;
  return <div className="min-h-screen lg:grid lg:grid-cols-[238px_1fr]">{drawer&&<div className="fixed inset-0 z-50 lg:hidden"><button aria-label="Close menu" onClick={()=>setDrawer(false)} className="absolute inset-0 bg-black/40"/><div className="relative h-full w-[270px]">{sidebar}</div></div>}<div className="hidden lg:block">{sidebar}</div><div className="min-w-0"><header className="sticky top-0 z-30 flex h-[68px] items-center justify-between border-b border-[#E6DED2] bg-[#F8F5EF]/95 px-5 backdrop-blur-sm sm:px-9"><div className="flex items-center gap-3"><button onClick={()=>setDrawer(true)} className="p-2 text-[#62594E] lg:hidden" aria-label="Open navigation"><Menu size={19}/></button><div><p className="text-[9px] uppercase tracking-[.18em] text-[#9A8665]">NARMIRA / ADMIN</p><p className="mt-1 font-serif text-[18px] capitalize leading-none">{title.replace('-',' ')}</p></div></div><div className="flex items-center gap-3"><span className="hidden text-xs text-[#81776B] sm:block">{new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'2-digit',month:'short'}).format(new Date())}</span><div className="h-7 w-px bg-[#E3D9CB]"/><div className="grid h-8 w-8 place-items-center border border-[#D8C8B3] bg-white font-serif text-sm text-[#632D35]">{admin?.name.slice(0,1).toUpperCase()}</div></div></header><main className="mx-auto max-w-[1500px] px-5 py-8 sm:px-9 sm:py-10"><Outlet/></main></div></div>;
};

const PageHeading: React.FC<{ eyebrow: string; title: string; description?: string; action?: React.ReactNode }> = ({eyebrow,title,description,action})=><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><p className="text-[9px] uppercase tracking-[.22em] text-[#9A8665]">{eyebrow}</p><h1 className="mt-2 font-serif text-[34px] leading-tight">{title}</h1>{description&&<p className="mt-2 text-sm text-[#81776B]">{description}</p>}</div>{action}</div>;
const StatePanel: React.FC<{error?:string;retry?:()=>void;empty?:boolean;children?:React.ReactNode}> = ({error,retry,empty,children})=><div className="admin-surface px-6 py-14 text-center">{error?<><CircleAlert className="mx-auto text-[#A8544D]" size={25}/><p className="mx-auto mt-3 max-w-lg text-sm text-[#6E5E55]">{error}</p>{retry&&<button className="admin-button-secondary mt-5" onClick={retry}><RefreshCw size={15}/>Try again</button>}</>:empty?<><div className="mx-auto grid h-12 w-12 place-items-center border border-[#E7DCCB] bg-[#FCFAF6] text-[#9A8665]"><Sparkles size={20}/></div><h2 className="mt-4 font-serif text-2xl">Your catalog is ready to begin.</h2><p className="mt-2 text-sm text-[#81776B]">A thoughtful first addition gives your collection its starting point.</p>{children}</>:<div className="flex justify-center py-4 text-[#7B7165]"><LoaderCircle size={20} className="animate-spin"/><span className="ml-2 text-sm">Loading your workspace…</span></div>}</div>;

const useCatalog = () => {
  const [products,setProducts]=useState<Product[]>([]); const [categories,setCategories]=useState<Category[]>([]); const [collections,setCollections]=useState<Collection[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState('');
  const load=useCallback(async()=>{setLoading(true);setError('');try{const [p,c,k]=await Promise.all([adminApi.products(),adminApi.categories(),adminApi.collections()]);setProducts(p.data);setCategories(c.data);setCollections(k.data);}catch(e){setError((e as Error).message);}finally{setLoading(false);}},[]);
  useEffect(()=>{void load();},[load]); return {products,categories,collections,loading,error,load,setProducts};
};

const OverviewPage: React.FC = () => {
  const {admin}=useAuth(); const {products,categories,collections,loading,error,load}=useCatalog(); const [activity,setActivity]=useState<{action:string;createdAt:string;entityType:string;admin:{name:string}}[]>([]); const [activityError,setActivityError]=useState(''); const canAudit=admin?.role==='SUPER_ADMIN';
  useEffect(()=>{if(!canAudit)return;adminApi.audit().then(r=>setActivity(r.data.slice(0,5))).catch(e=>setActivityError(e instanceof AdminApiError&&e.status===403?'':e.message));},[canAudit]);
  if(loading)return <><PageHeading eyebrow="Your atelier" title="A considered overview" description="A clear view of the collection you are building."/><StatePanel/></>;
  if(error)return <><PageHeading eyebrow="Your atelier" title="A considered overview"/><StatePanel error={error} retry={()=>void load()}/></>;
  const active=products.filter(p=>p.status==='ACTIVE').length,draft=products.filter(p=>p.status==='DRAFT').length,archived=products.filter(p=>p.status==='ARCHIVED').length;
  const lowStock=products.flatMap(p=>p.inventory.map(i=>({product:p,inventory:i}))).filter(r=>r.inventory.stockQuantity-r.inventory.reservedQuantity<=5);
  return <><PageHeading eyebrow="Your atelier" title="A considered overview" description="A clear view of the collection you are building." action={<Link to="/admin/products/new" className="admin-button-primary"><Plus size={16}/>Add a product</Link>}/>
    {products.length===0?<StatePanel empty><Link to="/admin/products/new" className="admin-button-primary mx-auto mt-6"><Plus size={16}/>Add your first product</Link></StatePanel>:<>
      <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">{[{label:'All products',value:products.length,detail:'Across every status',icon:ShoppingBag},{label:'Published',value:active,detail:'Visible to customers',icon:Check},{label:'Drafts',value:draft,detail:'In the making',icon:ClipboardList},{label:'Archived',value:archived,detail:'Not currently listed',icon:Package}].map((card,index)=><div className="admin-surface p-5 sm:p-6" key={card.label}><div className="flex items-center justify-between"><span className="text-[10px] uppercase tracking-[.14em] text-[#887E71]">{card.label}</span><card.icon size={16} className={index===1?'text-[#75836B]':'text-[#A58C5F'}/></div><p className="mt-5 font-serif text-4xl">{card.value}</p><p className="mt-1 text-[10px] text-[#9B9184]">{card.detail}</p></div>)}</div>
      <div className="mt-5 grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><section className="admin-surface"><div className="flex items-center justify-between border-b border-[#EEE7DD] px-5 py-4 sm:px-6"><div><p className="text-[9px] uppercase tracking-[.18em] text-[#9A8665]">Catalog</p><h2 className="mt-1 font-serif text-xl">Recently updated</h2></div><Link to="/admin/products" className="text-[10px] text-[#632D35] underline underline-offset-4">View all</Link></div><div className="divide-y divide-[#F0EBE4]">{[...products].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,5).map(p=><Link to={`/admin/products/${p.id}`} key={p.id} className="flex items-center gap-3 px-5 py-3.5 hover:bg-[#FCFAF6] sm:px-6"><ProductThumb product={p}/><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium">{p.name}</p><p className="mt-1 text-[10px] text-[#9A9084]">{p.sku||p.slug} · Updated {date(p.updatedAt)}</p></div><StatusPill status={p.status}/></Link>)}</div></section>
      <section className="admin-surface"><div className="border-b border-[#EEE7DD] px-5 py-4 sm:px-6"><p className="text-[9px] uppercase tracking-[.18em] text-[#9A8665]">At a glance</p><h2 className="mt-1 font-serif text-xl">Your assortment</h2></div><div className="divide-y divide-[#F0EBE4]">{[{label:'Categories',value:categories.length,to:'/admin/categories',icon:Shapes},{label:'Collections',value:collections.length,to:'/admin/collections',icon:Tags},{label:'Low stock',value:lowStock.length,to:'/admin/inventory',icon:Boxes}].map(row=><Link key={row.label} to={row.to} className="flex items-center gap-3 px-5 py-4 hover:bg-[#FCFAF6] sm:px-6"><row.icon size={16} className="text-[#9A8665]"/><span className="flex-1 text-xs">{row.label}</span><span className="font-serif text-xl">{row.value}</span><ChevronRight size={14} className="text-[#ACA294]"/></Link>)}</div>{lowStock.length>0&&<p className="px-5 py-3 text-[10px] text-[#99713E] sm:px-6">{lowStock.length} combination{lowStock.length===1?'':'s'} at 5 units or fewer</p>}</section></div>
      {canAudit&&<section className="admin-surface mt-5"><div className="flex items-center justify-between border-b border-[#EEE7DD] px-5 py-4 sm:px-6"><div><p className="text-[9px] uppercase tracking-[.18em] text-[#9A8665]">Super administrator</p><h2 className="mt-1 font-serif text-xl">Recent activity</h2></div><Link to="/admin/audit" className="text-[10px] text-[#632D35] underline underline-offset-4">Open activity log</Link></div>{activityError?<p className="px-6 py-5 text-xs text-[#8B5048]">{activityError}</p>:activity.length===0?<p className="px-6 py-5 text-xs text-[#8B8175]">No recorded activity yet.</p>:<div className="grid gap-2 p-5 sm:grid-cols-2 xl:grid-cols-5">{activity.map((entry,i)=><div key={`${entry.action}-${entry.createdAt}-${i}`} className="border-l border-[#D6C29C] pl-3"><p className="text-[10px] font-medium">{entry.action.toLowerCase().replaceAll('_',' ')}</p><p className="mt-1 text-[9px] text-[#958A7D]">{entry.admin.name} · {date(entry.createdAt)}</p></div>)}</div>}</section>}
    </>}</>;
};

const ProductThumb: React.FC<{product:Product}> = ({product})=>{const src=product.images[0]?.imageUrl;return <div className="h-12 w-10 shrink-0 overflow-hidden bg-[#F0EAE0]">{src?<img src={src} alt="" className="h-full w-full object-cover"/>:<div className="grid h-full place-items-center font-serif text-lg text-[#B6A88F]">N</div>}</div>};
const StatusPill: React.FC<{status:string}> = ({status})=><span className={`inline-flex items-center gap-1.5 border px-2 py-1 text-[9px] uppercase tracking-[.1em] ${status==='ACTIVE'?'border-[#CCD7C5] bg-[#F2F6EF] text-[#5C7151]':status==='ARCHIVED'?'border-[#DDD5CA] bg-[#F4F1EC] text-[#797064]':'border-[#E7D7BA] bg-[#FBF6E9] text-[#99753F]'}`}><i className={`h-1.5 w-1.5 rounded-full ${status==='ACTIVE'?'bg-[#708762]':status==='ARCHIVED'?'bg-[#958B7D]':'bg-[#B59A68]'}`}/>{status.toLowerCase()}</span>;

const ProductsPage: React.FC = () => {
  const {products,loading,error,load}=useCatalog(); const notice=useNotice(); const {admin}=useAuth(); const [query,setQuery]=useState('');const [status,setStatus]=useState('ALL');const [page,setPage]=useState(1);const [busy,setBusy]=useState('');const [confirm,setConfirm]=useState<{product:Product;action:'archive'|'publish'|'unpublish'|'restore'}|null>(null); const size=8;
  const filtered=products.filter(p=>(status==='ALL'||p.status===status)&&`${p.name} ${p.sku??''} ${p.slug} ${p.categories.map(c=>c.category.name).join(' ')}`.toLowerCase().includes(query.toLowerCase())); const pages=Math.max(1,Math.ceil(filtered.length/size));const visible=filtered.slice((page-1)*size,page*size);
  async function runAction(){if(!confirm)return;const {product,action}=confirm;setBusy(product.id);try{await adminApi.lifecycle(product.id,action);notice(`Product ${action==='publish'?'published':action==='archive'?'archived':action==='restore'?'restored as draft':'returned to draft'}.`);await load();}catch(e){notice((e as Error).message,'error');}finally{setBusy('');setConfirm(null);}}
  return <><PageHeading eyebrow="The collection" title="Products" description={`${products.length} product${products.length===1?'':'s'} in your catalog.`} action={<Link to="/admin/products/new" className="admin-button-primary"><Plus size={16}/>New product</Link>}/>
    <div className="admin-surface mb-4 flex flex-wrap items-center gap-3 p-4"><div className="relative min-w-[220px] flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9C9285]"/><input className="admin-input !h-10 pl-9" aria-label="Search products" value={query} onChange={e=>{setQuery(e.target.value);setPage(1)}} placeholder="Search name, SKU or category"/></div><SlidersHorizontal size={15} className="text-[#9C9285]"/><select className="admin-select !h-10 min-w-[145px]" aria-label="Filter status" value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}}><option value="ALL">Every status</option><option value="ACTIVE">Published</option><option value="DRAFT">Draft</option><option value="ARCHIVED">Archived</option></select><button onClick={()=>void load()} aria-label="Refresh products" className="admin-icon-button"><RefreshCw size={15}/></button></div>
    {loading?<StatePanel/>:error?<StatePanel error={error} retry={()=>void load()}/>:products.length===0?<StatePanel empty><Link to="/admin/products/new" className="admin-button-primary mx-auto mt-6"><Plus size={16}/>Add your first product</Link></StatePanel>:filtered.length===0?<div className="admin-surface py-16 text-center"><Search className="mx-auto text-[#B7AA98]"/><p className="mt-3 font-serif text-xl">No products match this view.</p><button className="mt-3 text-xs text-[#632D35] underline" onClick={()=>{setQuery('');setStatus('ALL')}}>Clear search and filters</button></div>:<>
      <div className="admin-surface overflow-hidden"><div className="hidden grid-cols-[minmax(220px,1.8fr)_1fr_1fr_.8fr_.8fr_auto] gap-4 border-b border-[#EDE5DA] bg-[#FCFAF6] px-5 py-3 text-[9px] uppercase tracking-[.13em] text-[#94897A] lg:grid"><span>Product</span><span>Category</span><span>SKU</span><span>Price</span><span>Status</span><span>Actions</span></div><div className="divide-y divide-[#F0EBE4]">{visible.map(p=><div key={p.id} className="grid gap-3 p-4 sm:p-5 lg:grid-cols-[minmax(220px,1.8fr)_1fr_1fr_.8fr_.8fr_auto] lg:items-center lg:gap-4"><div className="flex min-w-0 items-center gap-3"><ProductThumb product={p}/><div className="min-w-0"><Link to={`/admin/products/${p.id}`} className="block truncate text-xs font-medium hover:text-[#632D35]">{p.name}</Link><p className="mt-1 truncate text-[10px] text-[#988E81]">Updated {date(p.updatedAt)}</p><div className="mt-2 lg:hidden"><StatusPill status={p.status}/></div></div></div><div className="hidden text-xs text-[#776E62] lg:block">{p.categories.map(c=>c.category.name).join(', ')||'—'}</div><div className="hidden text-[11px] text-[#776E62] lg:block">{p.sku||'—'}</div><div className="text-xs">{money(p.salePrice??p.basePrice)}{p.salePrice&&<span className="ml-2 text-[10px] text-[#9A9084] line-through">{money(p.basePrice)}</span>}</div><div className="hidden lg:block"><StatusPill status={p.status}/></div><div className="flex flex-wrap items-center gap-1 lg:justify-end">{p.status==='ACTIVE'&&<Link title="Preview public product" to={`/product/${p.slug}`} target="_blank" className="admin-icon-button"><Eye size={15}/></Link>}<Link title="Edit product" to={`/admin/products/${p.id}`} className="admin-icon-button"><ChevronRight size={16}/></Link>{admin?.role==='SUPER_ADMIN'&&(p.status==='DRAFT'?<button disabled={!!busy} onClick={()=>setConfirm({product:p,action:'publish'})} title="Publish" className="admin-icon-button"><ArrowUpRight size={15}/></button>:p.status==='ACTIVE'?<button disabled={!!busy} onClick={()=>setConfirm({product:p,action:'unpublish'})} title="Unpublish" className="admin-icon-button"><ArrowDownRight size={15}/></button>:<button disabled={!!busy} onClick={()=>setConfirm({product:p,action:'restore'})} title="Restore to draft" className="admin-icon-button"><RefreshCw size={14}/></button>)}{admin?.role==='SUPER_ADMIN'&&p.status!=='ARCHIVED'&&<button disabled={!!busy} onClick={()=>setConfirm({product:p,action:'archive'})} title="Archive" className="admin-icon-button hover:!text-[#963D3A]"><Package size={15}/></button>}</div></div>)}</div><div className="flex items-center justify-between border-t border-[#EDE5DA] px-4 py-3"><p className="text-[10px] text-[#8D8376]">Showing {(page-1)*size+1}–{Math.min(page*size,filtered.length)} of {filtered.length}</p><div className="flex items-center gap-2"><button disabled={page===1} onClick={()=>setPage(page-1)} aria-label="Previous page" className="admin-icon-button"><ChevronLeft size={16}/></button><span className="text-[10px]">{page} / {pages}</span><button disabled={page===pages} onClick={()=>setPage(page+1)} aria-label="Next page" className="admin-icon-button"><ChevronRight size={16}/></button></div></div></div>
    </>}
    {confirm&&<ConfirmDialog title={`${confirm.action[0].toUpperCase()+confirm.action.slice(1)} ${confirm.product.name}?`} message={confirm.action==='publish'?'The backend will validate product readiness before it becomes visible to customers.':confirm.action==='archive'?'This removes the product from the public catalog. You can restore it to draft later.':confirm.action==='unpublish'?'This product will leave the public catalog and return to draft.':'This product will return to draft and remain unpublished.'} confirmLabel={confirm.action==='archive'?'Archive product':confirm.action==='publish'?'Publish product':confirm.action==='restore'?'Restore as draft':'Unpublish'} busy={!!busy} onClose={()=>setConfirm(null)} onConfirm={()=>void runAction()}/>}</>;
};

const ProductEditor: React.FC = () => {
  const {id}=useParams(); const navigate=useNavigate(); const notice=useNotice(); const {categories,collections}=useCatalog(); const [product,setProduct]=useState<Product|null>(null); const [loading,setLoading]=useState(!!id); const [error,setError]=useState(''); const [busy,setBusy]=useState(false); const [dirty,setDirty]=useState(false); const [images,setImages]=useState(''); const [variant,setVariant]=useState({name:'',colorName:'',colorCode:'#632D35',sku:''}); const [sizeLabels,setSizeLabels]=useState(''); const [stock,setStock]=useState('0'); const [reason,setReason]=useState(''); const [confirmLeave,setConfirmLeave]=useState(false);
  useEffect(()=>{if(!id)return;adminApi.product(id).then(p=>{setProduct(p);setImages(p.images.filter(i=>!i.variantId).map(i=>i.imageUrl).join('\n'));setSizeLabels(p.sizes.filter(s=>s.isAvailable).map(s=>s.size).join(', '));const first=p.variants.find(v=>v.isActive);if(first)setVariant({name:first.name,colorName:first.colorName,colorCode:first.colorCode,sku:first.sku??''});}).catch(e=>setError((e as Error).message)).finally(()=>setLoading(false));},[id]);
  useEffect(()=>{if(!dirty)return;const handler=(event:BeforeUnloadEvent)=>{event.preventDefault();};window.addEventListener('beforeunload',handler);return()=>window.removeEventListener('beforeunload',handler);},[dirty]);
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const name=text(form.get('name'));const payload:ProductInput={name,slug:text(form.get('slug'))||slugify(name),description:text(form.get('description')),shortDescription:text(form.get('shortDescription')),sku:text(form.get('sku')),basePrice:text(form.get('basePrice')),salePrice:text(form.get('salePrice'))||null,material:text(form.get('material')),weaveOrigin:text(form.get('weaveOrigin')),careInstructions:text(form.get('careInstructions')),details:text(form.get('details')).split('\n').map(x=>x.trim()).filter(Boolean),tags:text(form.get('tags')).split(',').map(x=>x.trim()).filter(Boolean),featured:form.has('featured'),bestseller:form.has('bestseller'),newArrival:form.has('newArrival'),categoryIds:Array.from(form.getAll('categoryIds'),String),collectionIds:Array.from(form.getAll('collectionIds'),String)};
    if(!payload.categoryIds.length){setError('Choose at least one category before saving a product.');return;} setError('');setBusy(true);
    try{let saved=id?await adminApi.updateProduct(id,payload):await adminApi.createProduct(payload);const imageRefs=images.split('\n').map(x=>x.trim()).filter(Boolean);for(const image of saved.images.filter(i=>!i.variantId))if(!imageRefs.includes(image.imageUrl))await adminApi.deleteImage(saved.id,image.id);for(const [index,url] of imageRefs.entries()){const existing=saved.images.find(image=>!image.variantId&&image.imageUrl===url);if(existing)await adminApi.updateImage(saved.id,existing.id,{imageUrl:url,altText:name,sortOrder:index,isPrimary:index===0});else await adminApi.addImage(saved.id,url,name,index);}
      if(variant.colorName.trim()){const current=saved.variants.find(v=>v.isActive);if(current)await adminApi.updateVariant(saved.id,current.id,{...variant,name:variant.name||variant.colorName});else await adminApi.addVariant(saved.id,{...variant,name:variant.name||variant.colorName});}
      const newSizes=sizeLabels.split(',').map(x=>x.trim()).filter(Boolean);for(const [index,label] of newSizes.entries()){const current=saved.sizes.find(s=>s.size.toLowerCase()===label.toLowerCase());if(current)await adminApi.updateSize(saved.id,current.id,{sortOrder:index,isAvailable:true});else await adminApi.addSize(saved.id,label,index);}for(const current of saved.sizes)if(current.isAvailable&&!newSizes.some(label=>label.toLowerCase()===current.size.toLowerCase()))await adminApi.updateSize(saved.id,current.id,{isAvailable:false});
      const refreshed=await adminApi.product(saved.id);setProduct(refreshed);setDirty(false);notice(id?'Product changes saved as draft.':'Draft created successfully.');navigate(`/admin/products/${saved.id}`,{replace:true});
    }catch(e){const err=e as AdminApiError;setError([err.message,...(err.issues??[])].join(' · '));}finally{setBusy(false);}}
  async function initializeStock(){if(!product)return;setBusy(true);try{for(const variantRow of product.variants.filter(v=>v.isActive)){const selectedSize=product.sizes.find(s=>s.isAvailable);await adminApi.setInventory(product.id,{variantId:variantRow.id,...(selectedSize?{sizeId:selectedSize.id}:{}),quantity:Number(stock),version:product.inventory.find(i=>i.variantId===variantRow.id&&i.sizeId===(selectedSize?.id??null))?.version??0,reason:reason.trim()||'Initial stock'});}const fresh=await adminApi.product(product.id);setProduct(fresh);notice('Inventory saved.');}catch(e){notice((e as Error).message,'error');}finally{setBusy(false);}}
  const guardNavigate=(to:string)=>{if(dirty){setConfirmLeave(true);return;}navigate(to);};
  if(loading)return <><PageHeading eyebrow="Catalog / Product" title="Loading product"/><StatePanel/></>;
  if(id&&error&&!product)return <><PageHeading eyebrow="Catalog / Product" title="Product unavailable"/><StatePanel error={error} retry={()=>window.location.reload()}/></>;
  return <><div className="mb-5 flex items-center gap-2 text-[10px] text-[#9A9084]"><button onClick={()=>guardNavigate('/admin/products')} className="hover:text-[#632D35]">Products</button><ChevronRight size={12}/><span>{id?'Edit product':'New product'}</span></div><PageHeading eyebrow={product?product.status:'Draft by default'} title={product?.name??'Create a product'} description="Save the core details as a draft, then complete images, options and stock." action={product&&<StatusPill status={product.status}/>}/>
    {error&&<div role="alert" className="mb-5 border border-[#E5C9C1] bg-[#FFF7F4] px-4 py-3 text-xs leading-6 text-[#79443B]">{error}</div>}
    <form onSubmit={submit} onChange={()=>setDirty(true)} className="space-y-5">
      <section className="admin-surface p-5 sm:p-7"><SectionTitle number="01" title="Product story" description="The details that introduce this piece to your collection."/><div className="mt-6 grid gap-4 md:grid-cols-2"><Field label="Product name" required><input className="admin-input" name="name" required maxLength={180} defaultValue={product?.name}/></Field><Field label="URL slug" hint="Lowercase letters, numbers and hyphens"><input className="admin-input" name="slug" defaultValue={product?.slug}/></Field><Field label="SKU"><input className="admin-input" name="sku" defaultValue={product?.sku??''}/></Field><Field label="Material / fabric"><input className="admin-input" name="material" defaultValue={product?.material??''} placeholder="Maheshwari silk-cotton"/></Field><Field label="Weave origin"><input className="admin-input" name="weaveOrigin" defaultValue={product?.weaveOrigin??'Maheshwar, Madhya Pradesh'}/></Field><Field label="Short description"><input className="admin-input" name="shortDescription" maxLength={500} defaultValue={product?.shortDescription??''}/></Field><Field label="Description" className="md:col-span-2"><textarea className="admin-input !h-28 !py-3" name="description" required maxLength={10000} defaultValue={product?.description}/></Field><Field label="Product details" hint="One detail per line" className="md:col-span-2"><textarea className="admin-input !h-24 !py-3" name="details" defaultValue={product?.details.join('\n')}/></Field><Field label="Care instructions" className="md:col-span-2"><textarea className="admin-input !h-20 !py-3" name="careInstructions" defaultValue={product?.careInstructions??''}/></Field></div></section>
      <section className="admin-surface p-5 sm:p-7"><SectionTitle number="02" title="Price & placement" description="Set the retail price and the places this piece belongs."/><div className="mt-6 grid gap-4 md:grid-cols-2"><Field label="Regular price · INR" required><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs text-[#8F8477]">₹</span><input className="admin-input pl-8" name="basePrice" type="number" min="0.01" step="0.01" required defaultValue={product?.basePrice}/></div></Field><Field label="Sale price · INR" hint="Must not exceed regular price"><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-xs text-[#8F8477]">₹</span><input className="admin-input pl-8" name="salePrice" type="number" min="0.01" step="0.01" defaultValue={product?.salePrice??''}/></div></Field><Field label="Categories" required className="md:col-span-2"><select className="admin-select min-h-11" name="categoryIds" multiple required defaultValue={product?.categories.map(c=>c.category.id)??[]}><option disabled value="">Select categories (Ctrl / ⌘ for multiple)</option>{categories.filter(c=>c.isActive).map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Field><Field label="Collections" hint="Optional · select multiple" className="md:col-span-2"><select className="admin-select min-h-11" name="collectionIds" multiple defaultValue={product?.collections.map(c=>c.collection.id)??[]}>{collections.filter(c=>c.isActive).map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></Field><Field label="Tags" hint="Separate with commas" className="md:col-span-2"><input className="admin-input" name="tags" defaultValue={product?.tags.join(', ')}/></Field><div className="flex flex-wrap gap-5 md:col-span-2">{[['featured','Featured'],['bestseller','Bestseller'],['newArrival','New arrival']].map(([key,label])=><label key={key} className="flex cursor-pointer items-center gap-2 text-xs"><input type="checkbox" name={key} defaultChecked={Boolean(product?.[key as 'featured'|'bestseller'|'newArrival'])} className="accent-[#632D35]"/>{label}</label>)}</div></div></section>
      <section className="admin-surface p-5 sm:p-7"><SectionTitle number="03" title="Images" description="Use approved HTTPS URLs or local /images and /assets references."/><Field className="mt-6" label="Image references" hint="One image reference per line. First image becomes the primary image."><textarea className="admin-input !h-28 !py-3" value={images} onChange={e=>{setImages(e.target.value);setDirty(true)}} placeholder="https://… or /images/collection-piece.webp"/></Field>{images.split('\n').filter(Boolean).length>0&&<div className="mt-4 flex gap-3 overflow-x-auto">{images.split('\n').filter(Boolean).map((src,i)=><div className="relative h-24 w-20 shrink-0 bg-[#F0EAE0]" key={`${src}-${i}`}><img src={src} alt={`Product image ${i+1}`} className="h-full w-full object-cover" onError={e=>{e.currentTarget.style.display='none'}}/><span className="absolute bottom-0 left-0 right-0 bg-[#302820]/75 px-1 py-1 text-center text-[8px] text-white">{i===0?'PRIMARY':`IMAGE ${i+1}`}</span></div>)}</div>}</section>
      <section className="admin-surface p-5 sm:p-7"><SectionTitle number="04" title="Options & sizes" description="Define color and size options for this piece."/><div className="mt-6 grid gap-4 md:grid-cols-2"><Field label="Color name"><input className="admin-input" value={variant.colorName} onChange={e=>{setVariant({...variant,colorName:e.target.value,name:e.target.value});setDirty(true)}} placeholder="e.g. Gulabi Rose"/></Field><Field label="Color code"><div className="flex gap-2"><input className="h-11 w-14 border border-[#E1D8CB] bg-white p-1" type="color" value={variant.colorCode} onChange={e=>setVariant({...variant,colorCode:e.target.value})}/><input className="admin-input" value={variant.colorCode} onChange={e=>setVariant({...variant,colorCode:e.target.value})}/></div></Field><Field label="Variant name"><input className="admin-input" value={variant.name} onChange={e=>setVariant({...variant,name:e.target.value})} placeholder="Color label"/></Field><Field label="Variant SKU"><input className="admin-input" value={variant.sku} onChange={e=>setVariant({...variant,sku:e.target.value})}/></Field><Field label="Sizes" hint="Comma-separated · e.g. Free Size, S, M, L" className="md:col-span-2"><input className="admin-input" value={sizeLabels} onChange={e=>{setSizeLabels(e.target.value);setDirty(true)}} placeholder="Free Size, S, M, L, XL"/></Field></div><p className="mt-4 flex items-start gap-2 text-[10px] leading-5 text-[#887D6F]"><CircleAlert size={14} className="mt-0.5 shrink-0 text-[#A58C5F]"/>Variants and sizes are created as separate catalog records. Inventory combinations are managed below. Saving never publishes automatically.</p></section>
      {product&&<section className="admin-surface p-5 sm:p-7"><SectionTitle number="05" title="Inventory" description="Stock is maintained by the backend for each color and size combination."/><div className="mt-5 space-y-2">{product.inventory.length===0?<p className="text-xs text-[#8B8175]">No stock records exist yet. Add a color and size, then initialize its stock.</p>:product.inventory.map(row=><div key={row.id} className="flex items-center gap-3 border-b border-[#F0EBE4] py-2 text-xs"><span className="flex-1">{product.variants.find(v=>v.id===row.variantId)?.colorName??'Default color'} / {product.sizes.find(s=>s.id===row.sizeId)?.size??'Default size'}</span><span className="text-[#766D62]">{row.stockQuantity} available · {row.reservedQuantity} reserved</span></div>)}</div><div className="mt-5 grid gap-3 md:grid-cols-[1fr_1fr_1.5fr_auto] md:items-end"><Field label="Set quantity"><input className="admin-input" type="number" min="0" value={stock} onChange={e=>setStock(e.target.value)}/></Field><Field label="Reason" className="md:col-span-2"><input className="admin-input" value={reason} onChange={e=>setReason(e.target.value)} placeholder="Required, e.g. Initial count"/></Field><button type="button" disabled={busy||!reason.trim()} onClick={()=>void initializeStock()} className="admin-button-secondary">{busy?<LoaderCircle size={15} className="animate-spin"/>:<Boxes size={15}/>}Set stock</button></div><p className="mt-2 text-[10px] text-[#94897B]">Stock entry above applies to the first active color and available size. Use Inventory for other combinations and adjustments.</p></section>}
      <div className="sticky bottom-3 z-20 flex flex-wrap items-center justify-between gap-3 border border-[#E8DFD4] bg-[#F8F5EF]/95 p-3 backdrop-blur"><p className="hidden text-[10px] text-[#8B8175] sm:block">New products are always saved as drafts.</p><div className="ml-auto flex gap-2"><button type="button" onClick={()=>guardNavigate('/admin/products')} className="admin-button-secondary">Cancel</button><button disabled={busy} className="admin-button-primary">{busy?<LoaderCircle size={15} className="animate-spin"/>:<Check size={15}/>}Save draft</button></div></div>
    </form>
    {confirmLeave&&<ConfirmDialog title="Leave without saving?" message="Your unsaved product changes will be lost." confirmLabel="Leave editor" onClose={()=>setConfirmLeave(false)} onConfirm={()=>{setConfirmLeave(false);setDirty(false);navigate('/admin/products')}}/>}
  </>;
};

import { useParams } from 'react-router-dom';
const SectionTitle:React.FC<{number:string;title:string;description:string}>=({number,title,description})=><div className="flex gap-3"><span className="font-serif text-sm text-[#B59A68]">{number}</span><div><h2 className="font-serif text-[22px] leading-none">{title}</h2><p className="mt-2 text-[11px] text-[#908578]">{description}</p></div></div>;
const Field:React.FC<{label:string;required?:boolean;hint?:string;className?:string;children:React.ReactNode}>=({label,required,hint,className='',children})=><label className={`block ${className}`}><span className="mb-2 block text-[10px] font-medium tracking-wide text-[#645B51]">{label}{required&&<i className="ml-1 text-[#9C5A51]">*</i>}</span>{children}{hint&&<span className="mt-1.5 block text-[9px] text-[#9A9084]">{hint}</span>}</label>;

const ResourcesPage:React.FC<{kind:'categories'|'collections'}>=({kind})=>{
  const isCategories=kind==='categories';const label=isCategories?'category':'collection';const {categories,collections,products,loading,error,load}=useCatalog();const rows=isCategories?categories:collections;const notice=useNotice();const [search,setSearch]=useState('');const [editing,setEditing]=useState<Category|Collection|null>(null);const [busy,setBusy]=useState(false);const [confirm,setConfirm]=useState<Category|Collection|null>(null);const [message,setMessage]=useState('');
  const filtered=rows.filter(r=>`${r.name} ${r.slug}`.toLowerCase().includes(search.toLowerCase()));
  async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const f=new FormData(event.currentTarget);const data:ResourceInput={name:text(f.get('name')),slug:text(f.get('slug'))||slugify(text(f.get('name'))),description:text(f.get('description')),image:text(f.get('image'))};setBusy(true);setMessage('');try{if(editing)await adminApi.updateResource(kind,editing.id,data);else await adminApi.createResource(kind,data);notice(`${label[0].toUpperCase()+label.slice(1)} ${editing?'updated':'created'}.`);setEditing(null);await load();}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}
  async function deactivate(){if(!confirm)return;setBusy(true);try{await adminApi.deactivateResource(kind,confirm.id);notice(`${label[0].toUpperCase()+label.slice(1)} deactivated.`);setConfirm(null);await load();}catch(e){notice((e as Error).message,'error');}finally{setBusy(false);}}
  const count=(id:string)=>products.filter(p=>isCategories?p.categories.some(x=>x.category.id===id):p.collections.some(x=>x.collection.id===id)).length;
  return <><PageHeading eyebrow="Catalog structure" title={isCategories?'Categories':'Collections'} description={isCategories?'Organize products into clear storefront categories.':'Curate related pieces into editorial collections.'} action={<button onClick={()=>{setEditing(null);setMessage('')}} className="admin-button-primary"><Plus size={16}/>New {label}</button>}/>
    <div className="admin-surface mb-4 p-4"><div className="relative max-w-md"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9C9285]"/><input className="admin-input !h-10 pl-9" aria-label={`Search ${label}s`} value={search} onChange={e=>setSearch(e.target.value)} placeholder={`Search ${label}s`}/></div></div>
    {loading?<StatePanel/>:error?<StatePanel error={error} retry={()=>void load()}/>:rows.length===0?<StatePanel empty><button onClick={()=>setEditing({id:'',name:'',slug:'',isActive:true,createdAt:'',updatedAt:''})} className="admin-button-primary mx-auto mt-6"><Plus size={16}/>Create your first {label}</button></StatePanel>:<div className="admin-surface overflow-hidden"><div className="hidden grid-cols-[1.4fr_1fr_.7fr_.6fr_auto] gap-4 border-b border-[#EDE5DA] bg-[#FCFAF6] px-5 py-3 text-[9px] uppercase tracking-[.13em] text-[#94897A] sm:grid"><span>Name</span><span>Slug</span><span>Products</span><span>Status</span><span>Actions</span></div><div className="divide-y divide-[#F0EBE4]">{filtered.map(row=><div key={row.id} className="grid gap-2 px-5 py-4 sm:grid-cols-[1.4fr_1fr_.7fr_.6fr_auto] sm:items-center sm:gap-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center bg-[#F2ECE2] text-[#9A8665]">{isCategories?<Shapes size={16}/>:<Tags size={16}/>}</div><div><p className="text-xs font-medium">{row.name}</p><p className="mt-1 text-[10px] text-[#9A9084] sm:hidden">{row.slug}</p></div></div><span className="hidden text-xs text-[#776E62] sm:block">/{row.slug}</span><span className="text-[10px] text-[#81776B]">{count(row.id)} linked product{count(row.id)===1?'':'s'}</span><span><StatusPill status={row.isActive?'ACTIVE':'ARCHIVED'}/></span><div className="flex gap-1"><button onClick={()=>{setEditing(row);setMessage('')}} className="admin-button-secondary !min-h-8 !px-3 !text-[10px]">Edit</button>{row.isActive&&<button onClick={()=>setConfirm(row)} className="admin-icon-button" aria-label={`Deactivate ${row.name}`} title="Deactivate"><X size={15}/></button>}</div></div>)}</div></div>}
    {editing&&<Modal onClose={()=>setEditing(null)} title={`${editing.id?'Edit':'New'} ${label}`}><form onSubmit={submit} className="space-y-4"><Field label="Name" required><input className="admin-input" name="name" required maxLength={120} defaultValue={editing.name}/></Field><Field label="Slug" required hint="Lowercase letters, numbers and hyphens"><input className="admin-input" name="slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" maxLength={140} defaultValue={editing.slug}/></Field><Field label="Description"><textarea className="admin-input !h-24 !py-3" name="description" maxLength={5000} defaultValue={editing.description??''}/></Field><Field label="Image reference" hint="Optional · HTTPS URL or /images, /assets path"><input className="admin-input" name="image" defaultValue={editing.image??''}/></Field>{message&&<p role="alert" className="text-xs text-[#963D3A]">{message}</p>}<div className="flex justify-end gap-2 pt-3"><button type="button" className="admin-button-secondary" onClick={()=>setEditing(null)}>Cancel</button><button disabled={busy} className="admin-button-primary">{busy&&<LoaderCircle size={15} className="animate-spin"/>}Save {label}</button></div></form></Modal>}
    {confirm&&<ConfirmDialog title={`Deactivate “${confirm.name}”?`} message={`This will make the ${label} inactive while retaining its product relationships. Products linked to it: ${count(confirm.id)}.`} confirmLabel="Deactivate" onClose={()=>setConfirm(null)} onConfirm={()=>void deactivate()} busy={busy}/>}
  </>;
};

const InventoryPage:React.FC=()=>{
  const {products,loading,error,load}=useCatalog();const [query,setQuery]=useState('');const [selected,setSelected]=useState<{product:Product;variantId:string|null;sizeId:string|null}|null>(null);const [quantity,setQuantity]=useState('');const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [confirm,setConfirm]=useState(false);const notice=useNotice();
  const rows=products.flatMap(product=>product.inventory.map(inv=>({product,inv,variant:product.variants.find(v=>v.id===inv.variantId),size:product.sizes.find(s=>s.id===inv.sizeId)}))).filter(row=>`${row.product.name} ${row.product.sku??''} ${row.variant?.colorName??''} ${row.size?.size??''}`.toLowerCase().includes(query.toLowerCase()));
  async function save(){if(!selected)return;setBusy(true);try{const product=selected.product;const inv=product.inventory.find(i=>i.variantId===selected.variantId&&i.sizeId===selected.sizeId);await adminApi.setInventory(product.id,{...(selected.variantId?{variantId:selected.variantId}:{}),...(selected.sizeId?{sizeId:selected.sizeId}:{}),quantity:Number(quantity),version:inv?.version??0,reason:reason.trim()});notice('Inventory adjustment recorded.');setConfirm(false);setSelected(null);setReason('');await load();}catch(e){const err=e as AdminApiError;notice(err.status===409?'Inventory changed while you were editing. Refresh the page and try again.':err.message,'error');if(err.status===409)await load();}finally{setBusy(false);}}
  return <><PageHeading eyebrow="Stock control" title="Inventory" description="Adjust stock using versioned records with a required reason."/><div className="admin-surface mb-4 flex items-center gap-3 p-4"><div className="relative max-w-md flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9C9285]"/><input className="admin-input !h-10 pl-9" aria-label="Search inventory" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search product, color or size"/></div><button className="admin-icon-button" aria-label="Refresh inventory" onClick={()=>void load()}><RefreshCw size={15}/></button></div>
    {loading?<StatePanel/>:error?<StatePanel error={error} retry={()=>void load()}/>:rows.length===0?<div className="admin-surface py-16 text-center"><Boxes className="mx-auto text-[#B2A590]"/><p className="mt-3 font-serif text-xl">No inventory records found.</p><p className="mt-2 text-xs text-[#8D8376]">Save a product with color or size options and record its initial stock.</p></div>:<div className="admin-surface overflow-hidden"><div className="hidden grid-cols-[1.4fr_1fr_.7fr_.7fr_.7fr_auto] gap-4 border-b border-[#EDE5DA] bg-[#FCFAF6] px-5 py-3 text-[9px] uppercase tracking-[.13em] text-[#94897A] sm:grid"><span>Product</span><span>Color</span><span>Size</span><span>On hand</span><span>Available</span><span/></div><div className="divide-y divide-[#F0EBE4]">{rows.map(({product,inv,variant,size})=><div key={inv.id} className="grid grid-cols-2 gap-3 px-5 py-4 sm:grid-cols-[1.4fr_1fr_.7fr_.7fr_.7fr_auto] sm:items-center"><Link to={`/admin/products/${product.id}`} className="truncate text-xs font-medium hover:text-[#632D35]">{product.name}</Link><span className="text-[11px] text-[#776E62]">{variant?.colorName??'Default'}</span><span className="text-[11px] text-[#776E62]">{size?.size??'Default'}</span><span className="text-xs">{inv.stockQuantity}</span><span className={`text-xs ${inv.stockQuantity-inv.reservedQuantity<=5?'text-[#9A6D37]':'text-[#66795B]'}`}>{inv.stockQuantity-inv.reservedQuantity}</span><button className="admin-button-secondary col-span-2 !min-h-8 !px-3 !text-[10px] sm:col-span-1" onClick={()=>{setSelected({product,variantId:variant?.id??null,sizeId:size?.id??null});setQuantity(String(inv.stockQuantity));setReason('')}}>Adjust stock</button></div>)}</div></div>}
    {selected&&!confirm&&<Modal title="Adjust stock" onClose={()=>setSelected(null)}><div className="mb-4 border-l-2 border-[#B59A68] pl-3"><p className="text-sm font-medium">{selected.product.name}</p><p className="mt-1 text-[10px] text-[#897F72]">{selected.product.variants.find(v=>v.id===selected.variantId)?.colorName??'Default'} / {selected.product.sizes.find(s=>s.id===selected.sizeId)?.size??'Default'}</p></div><Field label="Current quantity"> <p className="border border-[#E9E0D5] bg-[#FCFAF6] px-3 py-3 text-sm">{quantity}</p></Field><Field label="New quantity" required className="mt-4"><input className="admin-input" type="number" min="0" max="1000000" value={quantity} onChange={e=>setQuantity(e.target.value)}/></Field><Field label="Adjustment reason" required className="mt-4"><textarea className="admin-input !h-20 !py-3" maxLength={500} value={reason} onChange={e=>setReason(e.target.value)} placeholder="e.g. Cycle count correction"/></Field><div className="mt-5 flex justify-end gap-2"><button className="admin-button-secondary" onClick={()=>setSelected(null)}>Cancel</button><button disabled={!reason.trim()||!quantity||Number(quantity)<0} className="admin-button-primary" onClick={()=>setConfirm(true)}>Review adjustment</button></div></Modal>}
    {selected&&confirm&&<ConfirmDialog title="Confirm inventory adjustment" message={`Quantity will change from ${selected.product.inventory.find(i=>i.variantId===selected.variantId&&i.sizeId===selected.sizeId)?.stockQuantity??0} to ${quantity}. Reason: ${reason}`} confirmLabel="Record adjustment" busy={busy} onClose={()=>setConfirm(false)} onConfirm={()=>void save()}/>}
  </>;
};

const AuditPage:React.FC=()=>{const [entries,setEntries]=useState<Awaited<ReturnType<typeof adminApi.audit>>['data']>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [filter,setFilter]=useState('');const load=useCallback(()=>{setLoading(true);adminApi.audit().then(r=>{setEntries(r.data);setError('')}).catch(e=>setError((e as Error).message)).finally(()=>setLoading(false));},[]);useEffect(()=>load(),[load]);const filtered=entries.filter(e=>`${e.admin.name} ${e.action} ${e.entityType} ${e.entityId}`.toLowerCase().includes(filter.toLowerCase()));return <><PageHeading eyebrow="Administration" title="Activity log" description="An append-only record of catalog and administrator actions."/><div className="admin-surface mb-4 p-4"><div className="relative max-w-md"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9C9285]"/><input className="admin-input !h-10 pl-9" aria-label="Filter activity" value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Filter actor, action or entity"/></div></div>{loading?<StatePanel/>:error?<StatePanel error={error} retry={load}/>:entries.length===0?<div className="admin-surface py-16 text-center"><Activity className="mx-auto text-[#B2A590]"/><p className="mt-3 font-serif text-xl">No activity recorded yet.</p></div>:<div className="admin-surface divide-y divide-[#F0EBE4]">{filtered.map(entry=><div key={entry.id} className="grid gap-2 px-5 py-4 sm:grid-cols-[1.2fr_1fr_1fr_1fr] sm:items-center"><div><p className="text-xs font-medium">{entry.action.toLowerCase().replaceAll('_',' ')}</p><p className="mt-1 text-[10px] text-[#8D8376]">{entry.admin.name} · {entry.admin.role.replace('_',' ')}</p></div><p className="text-[10px] text-[#776E62]">{entry.entityType} · {entry.entityId.slice(0,12)}</p><p className="text-[10px] text-[#776E62]">{date(entry.createdAt)} · {new Intl.DateTimeFormat('en-IN',{hour:'2-digit',minute:'2-digit'}).format(new Date(entry.createdAt))}</p><p title={entry.requestId??''} className="truncate text-[9px] text-[#A09485]">Request {entry.requestId??'—'}</p></div>)}</div>}</>};

const SettingsPage:React.FC=()=>{const {admin,logout}=useAuth();return <><PageHeading eyebrow="Workspace" title="Settings" description="Your administrator account and secure session."/><div className="grid gap-5 xl:grid-cols-2"><section className="admin-surface p-6"><SectionTitle number="01" title="Administrator profile" description="Your role determines which catalog actions are available."/><dl className="mt-6 divide-y divide-[#F0EBE4]">{[['Name',admin?.name],['Email',admin?.email],['Role',admin?.role.replace('_',' ')],['Session','Secure HttpOnly cookie']].map(([k,v])=><div key={k} className="flex justify-between gap-4 py-3"><dt className="text-[10px] text-[#918779]">{k}</dt><dd className="text-xs capitalize">{v}</dd></div>)}</dl><div className="mt-5 flex items-start gap-2 border-l border-[#B59A68] bg-[#FCFAF6] p-3 text-[10px] leading-5 text-[#82776A]"><ShieldCheck size={15} className="mt-0.5 shrink-0 text-[#8D7957]"/>Session credentials are held in an HttpOnly cookie and are never stored in browser storage.</div></section><section className="admin-surface p-6"><SectionTitle number="02" title="Session" description="Sign out to revoke this administrator session."/><p className="mt-6 text-xs leading-6 text-[#81776B]">Your session expires after the backend session period. If your access expires, you will be returned to secure sign in.</p><button onClick={()=>void logout()} className="admin-button-secondary mt-5"><LogOut size={15}/>Sign out</button></section></div></>};

const Modal:React.FC<{title:string;onClose:()=>void;children:React.ReactNode}>=({title,onClose,children})=><div className="fixed inset-0 z-[70] flex items-center justify-center overflow-y-auto bg-[#302820]/45 p-4" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section role="dialog" aria-modal="true" aria-label={title} className="my-auto w-full max-w-lg border border-[#E5DCCE] bg-[#FDFBF7] p-6 shadow-xl"><div className="mb-5 flex items-center justify-between"><h2 className="font-serif text-2xl">{title}</h2><button aria-label="Close dialog" onClick={onClose} className="admin-icon-button"><X size={17}/></button></div>{children}</section></div>;
const ConfirmDialog:React.FC<{title:string;message:string;confirmLabel:string;onClose:()=>void;onConfirm:()=>void;busy?:boolean}>=({title,message,confirmLabel,onClose,onConfirm,busy})=><Modal title={title} onClose={onClose}><div className="flex gap-3"><CircleAlert size={19} className="mt-0.5 shrink-0 text-[#A27D48]"/><p className="text-xs leading-6 text-[#756B60]">{message}</p></div><div className="mt-6 flex justify-end gap-2"><button className="admin-button-secondary" onClick={onClose}>Cancel</button><button disabled={busy} className="admin-button-primary" onClick={onConfirm}>{busy&&<LoaderCircle size={15} className="animate-spin"/>}{confirmLabel}</button></div></Modal>;



